const { Suite } = require('benchmark');
const clsx = require('../src/index').default;
const lite = require('../src/lite').default;

function bench(name, ...args) {
	console.log(`\n# ${name}`);
	new Suite()
		.add('clsx        ', () => clsx.apply(clsx, args))
		.add('clsx/lite   ', () => lite.apply(lite, args))
		.on('cycle', e => console.log('  ' + e.target))
		.run();
}

bench(
	'Strings',
	'foo', '', 'bar', 'baz', 'bax', 'bux'
);

bench(
	'Objects',
	{ foo:true, bar:true, bax:true, bux:false },
	{ baz:true, bax:false, bux:true }
);

bench(
	'Arrays',
	['foo', 'bar'],
	['baz', 'bax', 'bux']
);

bench(
	'Mixed',
	'foo', 'bar',
	{ bax:true, bux:false },
	['baz', { bax:false, bux:true }]
);

